def caesar_shift(s: str, k: int) -> str:
    result = []
    for char in s:
        if char.isalpha():
            base = ord('A') if char.isupper() else ord('a')
            shifted = chr((ord(char) - base + k) % 26 + base)
            result.append(shifted)
        else:
            result.append(char)
    return ''.join(result)

