def lis_length(nums: list[int]) -> int:
    if not nums:
        return 0

    def binary_search(sub: list[int], val: int) -> int:
        left, right = 0, len(sub) - 1
        while left <= right:
            mid = (left + right) // 2
            if sub[mid] < val:
                left = mid + 1
            else:
                right = mid - 1
        return left

    sub = []
    for x in nums:
        pos = binary_search(sub, x)
        if pos == len(sub):
            sub.append(x)
        else:
            sub[pos] = x
    return len(sub)

