def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Empty string is not a valid duration")

    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    total_seconds = 0
    parts = s.split()

    for part in parts:
        if len(part) < 1 or part[-1] not in units:
            raise ValueError(f"Malformed duration part: {part}")
        value = int(part[:-1])
        total_seconds += value * units[part[-1]]

    return total_seconds

