def min_meeting_rooms(meetings: list[tuple[int, int]]) -> int:
    if not meetings:
        return 0

    # Sort meetings by start time
    meetings.sort(key=lambda x: x[0])

    # List to keep track of end times of meetings
    end_times = []

    for meeting in meetings:
        # If the meeting starts before the earliest end time, increase room count
        if not end_times or meetings[0][0] >= end_times[0]:
            end_times.append(meeting[1])
        else:
            # Find the earliest meeting that ends before the current meeting starts
