def n_queens(n: int) -> int:
    def solve(row, cols, diags1, diags2):
        if row == n:
            return 1
        count = 0
        for col in range(n):
            if col not in cols and row - col not in diags1 and row + col not in diags2:
                count += solve(row + 1, cols | {col}, diags1 | {row - col}, diags2 | {row + col})
