def sliding_max(nums: list[int], k: int) -> list[int]:
    if not nums or k <= 0:
        return []

    deque = []
    max_list = []

    for i, num in enumerate(nums):
        # Remove elements not part of the sliding window
        if deque and deque[0][0] < i - k + 1:
            deque.pop(0)

        # Maintain deque in decreasing order
        while deque and deque[-1][1] <= num:
            deque.pop()

        deque.append((i, num))

        # If first window is reached, start adding to max_list
        if i >= k - 1:
            max_list.append(deque[0][1])

    return max_list

