    start, end = 0, 0
    for i in range(len(s)):
        odd = expand_around_center(i, i)
        even = expand_around_center(i, i + 1)

        if len(odd) > len(even):
            longest = odd
        else:
            longest = even

        if len(longest) > (end - start):
            start = i - (len(longest) - 1) // 2
