    for i in range(len(s)):
        len1 = expand_around_center(s, i, i)
        len2 = expand_around_center(s, i, i + 1)
        len_longest = max(len1, len2)
        if len_longest > end - start:
            start = i - (len_longest - 1) // 2
            end = i + len_longest // 2

