def evaluate(expr: str) -> int:
    def apply_operator(operators, values):
        right = values.pop()
        left = values.pop()
        op = operators.pop()
        if op == '+':
            values.append(left + right)
        elif op == '-':
            values.append(left - right)
        elif op == '*':
            values.append(left * right)
        elif op == '/':
            values.append(left // right)  # Integer division truncating toward zero

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    operators = []
    values = []
    i = 0
    while i < len(expr):
        if expr[i] == ' ':
            i += 1
            continue
        if expr[i] in '0123456789':
            val = 0
            while i < len(expr) and expr[i].isdigit():
                val = val * 10 + int(expr[i])
                i += 1
            values.append(val)
            continue
        if expr[i] in '+-*/':
            while (operators and precedence(operators[-1]) >= precedence(expr[i])):
                apply_operator(operators, values)
            operators.append(expr[i])
        elif expr[i] == '(':
            operators.append(expr[i])
        elif expr[i] == ')':
            while operators and operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()  # Pop the '('
        i += 1

    while operators:
        apply_operator(operators, values)

    return values[0]

