def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Empty string")

    units = {"d": 86400, "h": 3600, "m": 60, "s": 1}
    total_seconds = 0

    for part in s.split():
        number = ''
        while s.startswith(('0', 'd', 'h', 'm', 's')) and len(s) > 0:
            if s[0] in 'dhms' or s[0].isdigit():
                number += s[0]
                s = s[1:]
            else:
                raise ValueError(f"Malformed duration part: {part}")
        if not number:
            raise ValueError(f"Malformed duration part: {part}")

        value = int(number)
        if part in units:
            total_seconds += value * units[part]
        else:
            raise ValueError(f"Unknown unit: {part}")

    return total_seconds

Final answer: <This function parses a duration string into total seconds and raises ValueError for empty or malformed strings.>

