def sliding_max(nums: list[int], k: int) -> list[int]:
    if not nums or k == 0:
        return []

    if k > len(nums):
        return [max(nums)]

    result = [0] * len(nums)
    deque = []

    for i in range(len(nums)):
        while deque and nums[deque[-1]] < nums[i]:
            deque.pop()

        result[i] = nums[i] if not deque or deque[0] == i - k else max(nums[i], nums[deque[0]])

        deque.append(i)

        if i >= k - 1:
            deque.pop(0)

    return result
