def paths_with_obstacles(grid: list[list[int]]) -> int:
    def is_valid(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == 0

    def count_paths(x, y):
        if not is_valid(x, y):
            return 0
        if x == len(grid) - 1 and y == len(grid[0]) - 1:
            return 1

        return (count_paths(x + 1, y) + count_paths(x, y + 1)) % 1000000007

    if grid[0][0] == 1 or grid[-1][-1] == 1:
        return 0

    return count_paths(0, 0) % 1000000007

